INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('junior_1', 'japanese', '漢文の「書き下し文」の説明として正しいものはどれか。', '["漢文を日本語の語順に直して読みやすくしたもの","中国語の発音で読んだもの","英語に翻訳したもの","漢文を省略して書いたもの"]', 0, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('junior_1', 'japanese', '返り点「一・二・三」が使われている場合、次に読むべきなのはどれか。', '["一の次は二、二の次は三","一の次は三、三の次は二","三の次は二、二の次は一","どれから読んでも良い"]', 0, 2);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('junior_1', 'japanese', 'レ点は何のために使われるか。', '["語順を日本語風に入れ替えるため","文の区切りを示すため","文字を強調するため","読み仮名を示すため"]', 0, 1);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('junior_1', 'japanese', '「一二点」と「上下点」が併用されている場合、どちらがより大きな範囲の入れ替えを示すか。', '["一二点","上下点","どちらも同じ","その時々による"]', 1, 3);
INSERT INTO quiz_questions (grade_level, category, question_text, options_json, correct_index, difficulty) VALUES ('junior_1', 'japanese', '書き下し文を作成する際、送り仮名はどこに書くか。', '["漢字の右下","漢字の左上","漢字の真下","漢字の真上"]', 0, 2);
